 function bubble(h){const src=imageSrc(h);if(!src)return null;const span=document.createElement('span');span.className='beta-hero-bubble beta-portrait-frame';const img=document.createElement('img');img.setAttribute('src',src);img.alt='';img.width=32;img.height=32;img.loading='lazy';img.decoding='async';span.append(img);const pip=document.createElement('span');pip.className='beta-wound-pip';pip.dataset.tier=h.dead?'fallen':String(h.wound?.tier||0);pip.setAttribute('aria-hidden','true');span.append(pip);span.title=(h.race||'Human')+' '+(h.className||'Warrior')+' · '+(h.dead?'Fallen':h.wound?(WOUND_TIERS[h.wound.tier]?.name||'Wounded')+' wound':'Healthy');return span}
 const head=v9PickHead;v9PickHead=function(h){const html=head.apply(this,arguments),portrait=bubble(h);if(!portrait)return html;const holder=document.createElement('div');holder.innerHTML=html;const crest=holder.querySelector('.beta-hero-crest');if(crest)crest.replaceWith(portrait);else holder.querySelector('.v9pick-name')?.prepend(portrait);return holder.innerHTML};
